  seq=[data['warmups_excluded'][key] if i==0 else data['samples'][key][i-1] for i,order in enumerate(data['orders']) for key in order]
  flat=[]
  for row in seq:
   assert row['checksum']==data['config']['expected'] and row['cpu_us']>0
   if row.get('children') is not None:
    assert len(row['children'])==data['config']['iterations'];assert sum(c['cpu_us'] for c in row['children'])==row['cpu_us'];assert sum(c['checksum'] for c in row['children'])==row['checksum'];flat.extend(row['children'])
   else:flat.append(row)
  assert len(data['cpu_queries'])==len(flat)
  for child,session in zip(flat,data['cpu_queries']):
   a,b=session['queries'][:2];assert a['child_affinity']==b['child_affinity']==[2]
   delta=((b['kernel_ns']+b['user_ns']-a['kernel_ns']-a['user_ns']) if meta['platform']=='windows' else b['cpu_ns']-a['cpu_ns'])/1000
   assert math.isclose(delta,child['cpu_us'],abs_tol=1e-7)
  med={k:statistics.median(v['cpu_us'] for v in rows) for k,rows in data['samples'].items()};assert med==data['medians_us'];a,b=med.values();assert math.isclose(data['change_percent'],100*(b/a-1),abs_tol=1e-9);assert math.isclose(data['delta_percent'],100*abs(b-a)/min(a,b),abs_tol=1e-9)
  batches+=len(seq);children_total+=len(flat);key=meta['platform']+'/'+meta['case'];case_groups.setdefault(key,{}).setdefault(stage,[]).append(data)
  groups.append({'file':path.name,'platform':meta['platform'],'case':meta['case'],'stage':stage,'series':meta['series'],'medians_us':med,'delta_percent':data['delta_percent'],'change_percent':data['change_percent'],'batches':len(seq),'children':len(flat)})
 for key,stages in case_groups.items():
  aa=stages.get('aa',[])
