   delta=max(x['delta_percent'] for x in aa);minimum=min(v for x in aa for v in x['medians_us'].values());entry=results['calibrations'][key];assert entry['delta_percent']==delta and entry['minimum_median_us']==minimum;assert entry['passed']==(delta<=2 and minimum>=5000000)
