 audits[label]={'results':results,'groups':groups,'batches_in_complete_groups_including_warmup':batches,'children_in_complete_groups':children_total,'successful_pilot_and_reference_children':pilots,'scope':'Raw API deltas/affinity/ordering/checksum sums/medians/gates audited. Complete but superseded pre-interruption groups retained as records, not used for resumed condition decision.'}
