 initial=audits['initial_'+variant]['results']['comparisons'];follow=audits['followup_value' if variant=='value' else 'local_after_pause']['results']['comparisons'];merged={**initial,**follow};targets={platform+'/'+case for platform in ('windows','linux') for case in protocol['cases']};assert len(targets)==52
